double nextCombatTrace = 0;
await Until(() =>
{
    var creature = game.Snapshot!.Creatures.Single(x => x.Id == rat);
    if (Now >= nextCombatTrace)
    {
        nextCombatTrace = Now + .5;
        GD.Print($"COMBAT_TRACE elapsed={Now - began:0.00} health={creature.Health:0.0} distance={Self.Position.Distance(creature.Position):0.00} range={ExperienceRules.WeaponRange(Self, game.Data):0.00} held={Field<bool>(game, \"attackKeyHeld\")} physical={Input.IsActionPressed(\"basic_attack\")} page={Field<string>(game, \"currentPage\")} stamina={Self.Stamina:0.0} cooldown={Self.Cooldowns.GetValueOrDefault(\"attack\") - game.Snapshot.Time:0.00} sequence={Self.LastAction - sequence}");
    }
    return creature.Health <= 0;
}, "Held Space did not resolve the normal starter encounter.", 15);
